1	//! End-to-end regression tests for `roottrace root`, focused on the power-of
2	//! two boundary in the RFC 6962 SHA-256 Merkle Tree Hash (7, 8 and 9
3	//! records).
4	//!
5	//! Expected roots are FIXED constants produced independently of roottrace by
6	//! `tests/reference/rfc6962_vectors.py`, which computes them with Python's
7	//! `hashlib.sha256` in two structurally different ways (the RFC's recursive
8	//! definition and an order-sensitive stack fold); the two implementations
9	//! agree for every vector, and the one-leaf/empty cases were additionally
10	//! cross-checked against the system `sha256sum`. The constants below are
11	//! copied from that generator and never derived from roottrace output.
12	//!
13	//! Each batch is spelled out as its exact record sequence so an expected root
14	//! can be traced back to the records it belongs to. Failures distinguish a
15	//! command execution failure from a root mismatch and report both the record
16	//! sequence and the expected root.
17	
18	use std::fs;
19	use std::path::PathBuf;
20	use std::process::Command;
21	use std::sync::atomic::{AtomicU64, Ordering};
22	
23	static COUNTER: AtomicU64 = AtomicU64::new(0);
24	
25	fn bin() -> &'static str {
26	    env!("CARGO_BIN_EXE_roottrace")
27	}
28	
29	/// File that is deleted when the guard drops, even if the test panics.
30	struct TempFile {
31	    path: PathBuf,
32	}
33	
34	impl TempFile {
35	    fn create(data: &[u8]) -> Self {
36	        let id = COUNTER.fetch_add(1, Ordering::Relaxed);
37	        let path = std::env::temp_dir().join(format!(
38	            "roottrace-regtest-{}-{}",
39	            std::process::id(),
40	            id,
41	        ));
42	        fs::write(&path, data).unwrap_or_else(|e| panic!("cannot create {}: {e}", path.display()));
43	        TempFile { path }
44	    }
45	}
46	
47	impl Drop for TempFile {
48	    fn drop(&mut self) {
49	        let _ = fs::remove_file(&self.path);
50	    }
51	}
52	
53	/// Temporary directory (used to trigger "path is a directory" failures).
54	struct TempDir {
55	    path: PathBuf,
56	}
57	
58	impl TempDir {
59	    fn create() -> Self {
60	        let id = COUNTER.fetch_add(1, Ordering::Relaxed);
61	        let path = std::env::temp_dir()
62	            .join(format!("roottrace-regtest-dir-{}-{}", std::process::id(), id));
63	        fs::create_dir(&path).unwrap();
64	        TempDir { path }
65	    }
66	}
67	
68	impl Drop for TempDir {
69	    fn drop(&mut self) {
70	        let _ = fs::remove_dir(&self.path);
71	    }
72	}
73	
74	fn join_lf(records: &[&[u8]], trailing_lf: bool) -> Vec<u8> {
75	    let mut data: Vec<u8> = Vec::new();
76	    for (i, rec) in records.iter().enumerate() {
77	        if i > 0 {
78	            data.push(b'\n');
79	        }
80	        data.extend_from_slice(rec);
81	    }
82	    if trailing_lf && !records.is_empty() {
83	        data.push(b'\n');
84	    }
85	    data
86	}
87	
88	/// Run `roottrace root <file>` and fully verify the documented success path:
89	/// exit status 0, empty stderr, stdout is exactly one line of 64 lowercase
90	/// hex digits terminated by a single LF, equal to `expected`.
91	fn assert_root(desc: &str, records: &[&[u8]], file_bytes: &[u8], expected: &str) {
92	    let tmp = TempFile::create(file_bytes);
93	    let output = Command::new(bin())
94	        .arg("root")
95	        .arg(&tmp.path)
96	        .output()
97	        .expect("failed to execute roottrace binary");
98	
99	    let sequence = records;
100	    if !output.status.success() || output.status.code() != Some(0) {
101	        panic!(
102	            "[{desc}] command execution failed for record sequence {sequence:?}\n\
103	             file bytes: {file_bytes:?}\n\
104	             expected root: {expected}\n\
105	             exit status: {:?}\n\
106	             stderr: {}\n\
107	             stdout: {}",
108	            output.status.code(),
109	            String::from_utf8_lossy(&output.stderr),
110	            String::from_utf8_lossy(&output.stdout),
111	        );
112	    }
113	    if !output.stderr.is_empty() {
114	        panic!(
115	            "[{desc}] successful run wrote to stderr for sequence {sequence:?}: {}",
116	            String::from_utf8_lossy(&output.stderr)
117	        );
118	    }
119	
120	    let stdout = &output.stdout;
121	    if stdout.len() != 65 || stdout[64] != b'\n' {
122	        panic!(
123	            "[{desc}] stdout is not exactly 64 hex digits + LF for sequence {sequence:?}: {stdout:?}"
124	        );
125	    }
126	    let hex = &stdout[..64];
127	    if !hex.iter().all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()) {
128	        panic!("[{desc}] root must be lowercase hex, got: {:?}", std::str::from_utf8(hex));
129	    }
130	    let actual = std::str::from_utf8(hex).unwrap();
131	    if actual != expected {
132	        panic!(
133	            "[{desc}] ROOT MISMATCH\n\
134	             record sequence: {sequence:?}\n\
135	             file bytes: {file_bytes:?}\n\
136	             expected root: {expected}\n\
137	             actual root:   {actual}"
138	        );
139	    }
140	}
141	
142	// ---------------------------------------------------------------------------
143	// Fixed record sequences.
144	//
145	// The 7/8/9 batches share their first seven records. Those seven include:
146	//   * duplicated content at two different positions (r0 == r4 == b"alpha")
147	//   * an empty record (r2)
148	//   * a trailing CR kept as content (r5)
149	//   * non-UTF-8 / NUL bytes (r6)
150	// The eighth and ninth records are explicitly defined and distinct.
151	// ---------------------------------------------------------------------------
152	
153	const B7: &[&[u8]] = &[
154	    b"alpha",
155	    b"beta",
156	    b"",
157	    b"gamma",
158	    b"alpha",
159	    b"delta\r",
160	    b"\xff\xfe\x00binary",
161	];
162	
163	const B8: &[&[u8]] = &[
164	    b"alpha",
165	    b"beta",
166	    b"",
167	    b"gamma",
168	    b"alpha",
169	    b"delta\r",
170	    b"\xff\xfe\x00binary",
171	    b"epsilon",
172	];
173	
174	const B9: &[&[u8]] = &[
175	    b"alpha",
176	    b"beta",
177	    b"",
178	    b"gamma",
179	    b"alpha",
180	    b"delta\r",
181	    b"\xff\xfe\x00binary",
182	    b"epsilon",
183	    b"zeta\x01tail",
184	];
185	
186	// Independently fixed RFC 6962 roots (tests/reference/rfc6962_vectors.py).
187	const ROOT_B7: &str = "90caa8bddc2a50cf863a969533ad1700a80aeed313dcd1c7a4b46b0c93991b6e";
188	const ROOT_B8: &str = "80f3f98ae8d7d9d1d2139a6a2dc94628e02fba22e125f922ea8a4c10799cb912";
189	const ROOT_B9: &str = "a8a3e76ecf28b850e84cb5465729921212ffd07de3c0e6e170cd233bf723adc3";
190	
191	// B9 with the duplicate-content position r4 changed to other bytes.
192	const V_DUP: &[&[u8]] = &[
193	    b"alpha",
194	    b"beta",
195	    b"",
196	    b"gamma",
197	    b"alpha-changed",
198	    b"delta\r",
199	    b"\xff\xfe\x00binary",
200	    b"epsilon",
201	    b"zeta\x01tail",
202	];
203	const ROOT_V_DUP: &str = "015cce68e9e800f3ff480da17c8f43f30eed95e0705b5500043c3bf74662dde0";
204	
205	// B9 with two records of different content (r1 and r5) swapped. The byte
206	// multiset of records is unchanged, only their positions differ.
207	const V_SWAP: &[&[u8]] = &[
208	    b"alpha",
209	    b"delta\r",
210	    b"",
211	    b"gamma",
212	    b"alpha",
213	    b"beta",
214	    b"\xff\xfe\x00binary",
215	    b"epsilon",
216	    b"zeta\x01tail",
217	];
218	const ROOT_V_SWAP: &str = "3a6482dbcf43884e11018c885ff68e63717a13154217c591c8a01f6dafdb9dd9";
219	
220	// B9 with the empty record r2 omitted: 8 records, but a DIFFERENT sequence
221	// from B8. Dropping an empty record must not be silently ignored.
222	const V_DROP_EMPTY: &[&[u8]] = &[
223	    b"alpha",
224	    b"beta",
225	    b"gamma",
226	    b"alpha",
227	    b"delta\r",
228	    b"\xff\xfe\x00binary",
229	    b"epsilon",
230	    b"zeta\x01tail",
231	];
232	const ROOT_V_DROP_EMPTY: &str = "918ae84b0d065be5148d048875c9f8cafb5e0ee14417cefbbbb4575631a5257a";
233	
234	// B9 with one extra duplicate of r0 appended: the same record content
235	// included twice occupies two positions (10 records total).
236	const V_DUP_INSERT: &[&[u8]] = &[
237	    b"alpha",
238	    b"beta",
239	    b"",
240	    b"gamma",
241	    b"alpha",
242	    b"delta\r",
243	    b"\xff\xfe\x00binary",
244	    b"epsilon",
245	    b"zeta\x01tail",
246	    b"alpha",
247	];
248	const ROOT_V_DUP_INSERT: &str = "ae0586f6c285c304a53273198d19f5f137d1d9f546e9a74a6fd87547c09bd4e8";
249	
250	// Empty file: zero records -> SHA-256(""). Single LF: one empty record ->
251	// SHA-256(0x00). Independently fixed (and cross-checked with sha256sum).
252	const ROOT_EMPTY_FILE: &str =
253	    "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855";
254	const ROOT_ONE_EMPTY_RECORD: &str =
255	    "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d";
256	
257	#[test]
258	fn roots_for_7_8_and_9_records_match_fixed_vectors() {
259	    assert_root(
260	        "B7: seven records (largest subtree split k=4, uneven right side)",
261	        B7,
262	        &join_lf(B7, true),
263	        ROOT_B7,
264	    );
265	    assert_root(
266	        "B8: eight records exactly fills a depth-3 tree (power-of-two boundary)",
267	        B8,
268	        &join_lf(B8, true),
269	        ROOT_B8,
270	    );
271	    assert_root(
272	        "B9: nine records crosses the 8-record power-of-two boundary (k=8)",
273	        B9,
274	        &join_lf(B9, true),
275	        ROOT_B9,
276	    );
277	}
278	
279	#[test]
280	fn changing_one_duplicate_position_gives_its_own_fixed_root() {
281	    assert_root(
282	        "V_DUP: r4 (byte-equal to r0) changed, exact new root",
283	        V_DUP,
284	        &join_lf(V_DUP, true),
285	        ROOT_V_DUP,
286	    );
287	    assert_ne!(ROOT_V_DUP, ROOT_B9, "changed record must change the root");
288	}
289	
290	#[test]
291	fn swapping_two_different_records_gives_its_own_fixed_root() {
292	    assert_root(
293	        "V_SWAP: r1 and r5 swapped; same record contents, different positions",
294	        V_SWAP,
295	        &join_lf(V_SWAP, true),
296	        ROOT_V_SWAP,
297	    );
298	    assert_ne!(ROOT_V_SWAP, ROOT_B9, "record order participates in the hash");
299	    // Equal contents at different positions are not interchangeable: while the
300	    // swap moved r1/r5, untouched duplicate positions r0 and r4 still prove
301	    // per-position participation via V_DUP's fixed root above.
302	}
303	
304	#[test]
305	fn omitting_the_empty_record_gives_its_own_fixed_root() {
306	    assert_eq!(V_DROP_EMPTY.len(), 8);
307	    assert_ne!(V_DROP_EMPTY, B8, "8 records here is not the B8 sequence");
308	    assert_root(
309	        "V_DROP_EMPTY: empty r2 removed; empty records occupy a real position",
310	        V_DROP_EMPTY,
311	        &join_lf(V_DROP_EMPTY, true),
312	        ROOT_V_DROP_EMPTY,
313	    );
314	    assert_ne!(ROOT_V_DROP_EMPTY, ROOT_B9);
315	    assert_ne!(ROOT_V_DROP_EMPTY, ROOT_B8, "must not collide with B8's 8-record root");
316	}
317	
318	#[test]
319	fn including_a_duplicate_record_twice_gives_its_own_fixed_root() {
320	    assert_eq!(V_DUP_INSERT.len(), 10);
321	    assert_root(
322	        "V_DUP_INSERT: duplicate of r0 appended; duplicates are not merged",
323	        V_DUP_INSERT,
324	        &join_lf(V_DUP_INSERT, true),
325	        ROOT_V_DUP_INSERT,
326	    );
327	    assert_ne!(ROOT_V_DUP_INSERT, ROOT_B9);
328	}
329	
330	#[test]
331	fn trailing_lf_only_terminates_the_last_record() {
332	    // The same fixed sequence with and without a final LF has the same fixed
333	    // root, on both sides of the power-of-two boundary.
334	    for (desc, records, expected) in [
335	        ("B7 trailing/no-trailing LF", B7, ROOT_B7),
336	        ("B8 trailing/no-trailing LF", B8, ROOT_B8),
337	        ("B9 trailing/no-trailing LF", B9, ROOT_B9),
338	    ] {
339	        assert_root(desc, records, &join_lf(records, true), expected);
340	        assert_root(desc, records, &join_lf(records, false), expected);
341	    }
342	}
343	
344	#[test]
345	fn empty_file_is_zero_records_single_lf_is_one_empty_record() {
346	    assert_root("EMPTY: 0-byte file, zero records", &[], b"", ROOT_EMPTY_FILE);
347	    assert_root(
348	        "ONE_LF: one LF, a single empty record",
349	        &[b""],
350	        b"\n",
351	        ROOT_ONE_EMPTY_RECORD,
352	    );
353	    assert_ne!(ROOT_EMPTY_FILE, ROOT_ONE_EMPTY_RECORD);
354	}
355	
356	#[test]
357	fn version_output_is_unchanged() {
358	    let out = Command::new(bin()).arg("--version").output().unwrap();
359	    assert_eq!(out.status.code(), Some(0));
360	    assert!(out.stderr.is_empty());
361	    assert_eq!(out.stdout, b"roottrace 0.1.0\n");
362	}
363	
364	#[test]
365	fn usage_errors_exit_2_and_write_usage_to_stderr() {
366	    let no_args = Command::new(bin()).output().unwrap();
367	    assert_eq!(no_args.status.code(), Some(2));
368	    assert!(no_args.stdout.is_empty());
369	    let err = String::from_utf8_lossy(&no_args.stderr);
370	    assert!(err.contains("Usage"), "expected usage on stderr, got: {err}");
371	
372	    for args in [
373	        vec!["bogus"],
374	        vec!["root"],
375	        vec!["root", "a", "b"],
376	        vec!["--version", "extra"],
377	    ] {
378	        let out = Command::new(bin()).args(&args).output().unwrap();
379	        assert_eq!(out.status.code(), Some(2), "args {args:?} should exit 2");
380	        assert!(out.stdout.is_empty(), "args {args:?} must not write stdout");
381	        assert!(
382	            String::from_utf8_lossy(&out.stderr).contains("Usage"),
383	            "args {args:?} should print usage to stderr"
384	        );
385	    }
386	}
387	
388	#[test]
389	fn read_failures_exit_1_and_write_nothing_to_stdout() {
390	    let missing = TempFile::create(b"x");
391	    let missing_path = missing.path.clone();
392	    drop(missing); // delete it so the path does not exist
393	    let out = Command::new(bin())
394	        .arg("root")
395	        .arg(&missing_path)
396	        .output()
397	        .unwrap();
398	    assert_eq!(out.status.code(), Some(1), "missing file should exit 1");
399	    assert!(out.stdout.is_empty());
400	    assert!(!out.stderr.is_empty());
401	
402	    let dir = TempDir::create();
403	    let out = Command::new(bin()).arg("root").arg(&dir.path).output().unwrap();
404	    assert_eq!(out.status.code(), Some(1), "directory path should exit 1");
405	    assert!(out.stdout.is_empty());
406	    assert!(!out.stderr.is_empty());
407	}
