1	//! End-to-end regression tests for `roottrace root` with LONG records whose
2	//! lengths approach and cross the SHA-256 padding/block boundaries.
3	//!
4	//! A leaf is hashed as SHA-256(0x00 || record). Record lengths 54/55/56 make
5	//! the leaf input 55/56/57 bytes (the 0x80 padding terminator and the 64-bit
6	//! length field crowd the 56-byte boundary and spill into a second block),
7	//! lengths 63/64/65 make it 64/65/66 bytes (exactly one block, then one and
8	//! two bytes into the next), and L135's leaf input is 136 bytes (content
9	//! reaches a third block). A block walk that drops the tail, counts a span
10	//! twice, pads wrong, or splits one record into several yields a different
11	//! root, which the fixed vectors below pin down.
12	//!
13	//! Expected roots are FIXED constants produced independently of roottrace by
14	//! `tests/reference/rfc6962_vectors.py` (standard-library `hashlib.sha256`,
15	//! recursive definition and stack fold agreeing); they are never derived
16	//! from roottrace output. The long record byte literals are copied from the
17	//! same generator, so the single-record batches and the mixed batch hash the
18	//! very same record bytes - a long record follows one standard on its own and
19	//! inside a batch.
20	//!
21	//! Every long record contains NUL, CR and non-UTF-8 bytes in its interior and
22	//! ends on a non-text byte, so no text decoding, CR/LF normalization or
23	//! NUL-based truncation can go unnoticed.
24	
25	mod common;
26	
27	use common::{assert_root, join_lf};
28	
29	// --- Fixed long records (raw record bytes, WITHOUT the LF separator) -------
30	// Copied verbatim from tests/reference/rfc6962_vectors.py output.
31	
32	const REC_L54: &[u8] =
33	    b"L54:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghi\x00";
34	const REC_L55: &[u8] =
35	    b"L55:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghij\r";
36	const REC_L56: &[u8] =
37	    b"L56:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijk\xff";
38	const REC_L63: &[u8] =
39	    b"L63:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqr\x00";
40	const REC_L64: &[u8] =
41	    b"L64:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrs\r";
42	const REC_L65: &[u8] =
43	    b"L65:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrst\xfe";
44	const REC_L135: &[u8] = b"L135:\x00\xff\xfe\rabcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopqrstuvwxyz0123456789abcdefghijklmnopq\xff";
45	
46	// Tail-byte variants: identical to the original except for the very last
47	// byte. Their fixed roots correspond to the whole MODIFIED record.
48	const REC_L65_M: &[u8] =
