103	    REC_L65_M,
104	    b"end-record\x01",
105	];
106	const ROOT_MIXED_M: &str = "71cc24ac8aa1e4e4c95ca35704b0ec4302323659479d3e46134fcb359ab2858e";
107	
108	/// Structural invariants every long record must satisfy: the exact required
109	/// raw length (LF excluded), no LF inside, and NUL/CR/non-UTF-8 bytes in the
110	/// interior.
111	fn assert_long_record_shape(name: &str, rec: &[u8], expected_len: usize) {
112	    assert_eq!(
113	        rec.len(),
114	        expected_len,
